import { normaliseText } from '../helpers/text.js';

/** The title as librarians file it: without a leading 'The', 'A' or 'An' (kept when nothing else is left). */
function filingTitle(title) {
  const stripped = title.trim().replace(/^(?:the|an|a)\s+/i, '');
  return stripped === '' ? title : stripped;
}

/** Returns the items whose title or author holds every word of the query, sorted by filing title. */
export function searchCatalog(items, query) {
  const words = normaliseText(query).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  return items
    .filter((item) => {
      const searchable = normaliseText(`${item.title} ${item.author}`);
      return words.every((word) => searchable.includes(word));
    })
    .sort(
      (first, second) =>
        filingTitle(first.title).localeCompare(filingTitle(second.title)) || first.title.localeCompare(second.title),
    );
}

